function minOperations(nums) {
  const n = nums.length;
  const allEqual = values => values.every(v => v === values[0]);
  if (n <= 4) {
    // Breadth-first search over every sequence of operations; each k is a difference between two original values.
    const amounts = new Set();
    for (const a of nums) for (const b of nums) if (a !== b) amounts.add(a - b);
    const seen = new Set([nums.join()]);
    let frontier = [nums];
    for (let steps = 0; ; steps++) {
      if (frontier.some(state => allEqual(state))) return steps;
      const next = [];
      for (const state of frontier) {
        for (let length = 1; length <= n; length++) {
          for (const k of amounts) {
            const after = state.map((v, i) => (i < length ? v + k : v));
            const key = after.join();
            if (!seen.has(key)) { seen.add(key); next.push(after); }
          }
        }
      }
      frontier = next;
    }
  }
  // Longer arrays: try every value of nums as the final value. Sweep from the right and, at each element that is off,
  // really add the missing amount to the whole prefix ending there. Keep the cheapest final value.
  let best = Infinity;
  for (const finalValue of new Set(nums)) {
    const current = [...nums];
    let used = 0;
    for (let i = n - 1; i >= 0; i--) {
      if (current[i] === finalValue) continue;
      const add = finalValue - current[i];
      for (let j = 0; j <= i; j++) current[j] += add;
      used++;
    }
    if (!allEqual(current)) throw new Error('The simulation did not make the array equal.');
    best = Math.min(best, used);
  }
  return best;
}

