function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const n = large ? 2000 - pick(100) : 1 + pick(7);
  const style = pick(5);
  const anyValue = () => pick(2000000001) - 1000000000;
  let nums;
  if (style === 0) {
    nums = Array.from({ length: n }, () => pick(5) - 2);
  } else if (style === 1) {
    nums = Array.from({ length: n }, anyValue);
  } else if (style === 2) {
    // Runs of equal values, so many neighbouring pairs already match.
    nums = [];
    while (nums.length < n) {
      const value = pick(21) - 10;
      const length = 1 + pick(large ? 40 : 3);
      for (let j = 0; j < length && nums.length < n; j++) nums.push(value);
    }
  } else if (style === 3) {
    nums = new Array(n).fill(anyValue());
  } else {
    nums = Array.from({ length: n }, () => (rand() < 0.5 ? -1000000000 : 1000000000));
  }
  return [nums];
}
